function validate([count]) {
  if (!Array.isArray(count) || count.length !== 256) return 'count must have exactly 256 entries.';
  if (count.some(c => !Number.isInteger(c) || c < 0 || c > 1e9)) return 'Each count is a whole number from 0 to 10^9.';
  const total = count.reduce((a, b) => a + b, 0);
  if (total < 1 || total > 1e9) return 'The sample must hold between 1 and 10^9 values.';
  const top = Math.max(...count);
  if (count.filter(c => c === top).length !== 1) return 'The most frequent value must be unique.';
  return null;
}

