function sampleStats(count) {
  let minimum = -1;
  let maximum = 0;
  let total = 0;
  let sum = 0;
  let mode = 0;
  for (let value = 0; value < count.length; value++) {
    if (count[value] === 0) continue;
    if (minimum === -1) minimum = value;
    maximum = value;
    total += count[value];
    sum += value * count[value];
    if (count[value] > count[mode]) mode = value;
  }
  const mean = sum / total;
  const lowRank = Math.floor((total + 1) / 2);
  const highRank = Math.floor(total / 2) + 1;
  let seen = 0;
  let low = -1;
  let high = -1;
  for (let value = minimum; value <= maximum; value++) {
    seen += count[value];
    if (low === -1 && seen >= lowRank) low = value;
    if (seen >= highRank) {
      high = value;
      break;
    }
  }
  const median = (low + high) / 2;
  return [minimum, maximum, mean, median, mode];
}

