function sampleStats(count) {
  // kth(k) walks the values from the bottom and returns the k-th smallest copy (0-based).
  const kth = (k) => {
    let passed = 0;
    for (let v = 0; v < 256; v++) {
      passed += count[v];
      if (passed > k) return v;
    }
    return -1;
  };
  let n = 0, total = 0;
  for (let v = 0; v < 256; v++) { n += count[v]; total += v * count[v]; }
  let mode = 255;
  for (let v = 254; v >= 0; v--) if (count[v] >= count[mode]) mode = v;
  const median = n % 2 === 1 ? kth((n - 1) / 2) : (kth(n / 2 - 1) + kth(n / 2)) / 2;
  return [kth(0), kth(n - 1), total / n, median, mode];
}

