function generate(rand, size) {
  const count = new Array(256).fill(0);
  const int = (k) => Math.floor(rand() * k);
  if (size === 'large') {
    const dense = rand() < 0.5;
    for (let v = 0; v < 256; v++) if (dense || rand() < 0.2) count[v] = int(3000000);
  } else {
    // Small samples cluster near a random spot or touch the edges 0 and 255.
    const spots = 1 + int(5), base = rand() < 0.3 ? 0 : rand() < 0.3 ? 250 : int(250);
    for (let i = 0; i < spots; i++) count[Math.min(255, base + int(6))] += 1 + int(4);
    if (rand() < 0.2) count[rand() < 0.5 ? 0 : 255] += 1 + int(3);
  }
  // Make the mode unique by giving one present value (or a fresh one) a strict lead.
  let top = Math.max(...count), mode = count.indexOf(top);
  if (top === 0) mode = int(256);
  count[mode] = top + 1 + (size === 'large' ? int(1000) : 0);
  return [count];
}
